#ifndef SAUTI_AAC_SBR_LD_TABLE_H
#define SAUTI_AAC_SBR_LD_TABLE_H
#include <stdint.h>
/* Prototype filter of the low-delay QMF (CLDFB) of AAC-LD / AAC-ELD SBR: 320 coefficients (decoder units: window = value / 64, i.e. 2^-6 of the 16-bit value), the
 * data of libxaac qmf_c_eld3 (generated by tools/gen_sbr_ld_qmf_table.py; Apache License 2.0, third_party/libxaac/NOTICE). */
extern const int16_t sauti_aac_sbr_ld_qmf_window[320];
/* The prototype of the 64-band synthesis of the dual rate: 640 coefficients (544 nonzero), same units (libxaac qmf_c_eld). */
extern const int16_t sauti_aac_sbr_ld_qmf_window64[640];
#endif
